class Solution {
public:
    vector<int> leftRightDifference(vector<int>& nums) {
        int n = nums.size();
        long long total = 0;
        for (int x : nums) total += x;
        vector<int> answer(n);
        long long leftSum = 0;
        for (int i = 0; i < n; i++) {
            long long rightSum = total - leftSum - nums[i];
            long long diff = leftSum - rightSum;
            if (diff < 0) diff = -diff;
            answer[i] = (int)diff;
            leftSum += nums[i];
        }
        return answer;
    }
};
